const entry  = msg.payload;
const source = msg.metadata.source;
const utils  = global.get("utils");

// Stale check
if (entry.timestamp <= source.timestamp) return null;

// Drop already-bridged messages (prevents cross-connection loops)
const bridgePattern = /^\[(?:wasos|rayvn|cim):/;
if (entry.text && bridgePattern.test(entry.text)) return null;

// Drop messages posted by the target (direct loop prevention)
const target_callsign = utils.build_callsign(msg.metadata.target);
if (entry.author.includes(target_callsign)) return null;

// Drop parat_bridge system messages
if (entry.text && entry.text.startsWith(utils.build_callsign({ client_system: "parat_bridge", name: "parat_bridge" }))) return null;

// Drop entries already labeled with target identifier
if ((entry.labels || []).some(l => l.id === msg.metadata.target.identifier)) return null;

return msg;
